<?php
namespace Tests\Feature;
use App\Models\{User,Customer,SalesInvoice}; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
class ReportTest extends TestCase { use RefreshDatabase; private function user(){return User::factory()->create(['role'=>'admin']);} private function invoice(string $date,string $number){$customer=Customer::firstOrCreate(['name'=>'Report Customer']);return SalesInvoice::create(['invoice_number'=>$number,'customer_id'=>$customer->id,'issue_date'=>$date,'due_date'=>$date,'subtotal'=>'100','tax_amount'=>'0','total'=>'100','status'=>'Paid']);} public function test_authenticated_user_can_load_reports(): void {$this->actingAs($this->user())->get(route('reports.index'))->assertOk()->assertSee('Sales vs Purchases by month');} public function test_date_filter_changes_report_data(): void {$this->invoice('2026-01-10','JAN');$this->invoice('2026-03-10','MAR');$response=$this->actingAs($this->user())->get(route('reports.index',['from'=>'2026-03-01','to'=>'2026-03-31']));$response->assertOk()->assertSee('100.00');} public function test_invalid_date_range_returns_validation_error(): void {$this->actingAs($this->user())->get(route('reports.index',['from'=>'2026-04-01','to'=>'2026-03-01']))->assertRedirect(route('reports.index'))->assertSessionHasErrors('from');} public function test_csv_download_has_text_csv_and_header(): void {$response=$this->actingAs($this->user())->get(route('reports.csv','sales-purchases'));$response->assertOk()->assertHeader('content-type','text/csv; charset=UTF-8');$this->assertStringContainsString('Month,Sales,Purchases',$response->streamedContent());} public function test_seeded_expenses_csv_contains_data_row(): void {$this->seed(\Database\Seeders\DatabaseSeeder::class);$response=$this->actingAs(User::first())->get(route('reports.csv','expenses',['from'=>now()->subYear()->toDateString(),'to'=>now()->toDateString()]));$content=$response->streamedContent();$this->assertStringContainsString('Category,Amount',$content);$this->assertGreaterThan(1,count(array_filter(explode("\n",trim($content))))); } }
